window.ENEM_RESOLUTION_CHUNKS=window.ENEM_RESOLUTION_CHUNKS||{};window.ENEM_RESOLUTION_CHUNKS["data/resolucoes/matematica_2023.js"]=[{"title":"Subtraia cone menor e perfuração","steps":["Os raios são 9 e 3 cm; a semelhança dá altura do cone menor 36 × 3/9 = 12 cm e do tronco 24 cm.","Com π = 3, V = 9² × 36 − 3² × 12 − 3 × 3² × 24 = 2 160 cm³.","A massa é 0,6 × 2 160 = 1 296 g, B."],"alternatives":{"A":"1 198,8 g equivale a volume menor que os 2 160 cm³ obtidos pelas duas retiradas.","B":"O volume restante multiplicado por 0,6 g/cm³ fornece 1 296 g.","C":"1 360,8 g não desconta corretamente as duas partes retiradas do cone original.","D":"4 665,6 g excede até a massa do cone inicial, que é 1 749,6 g.","E":"4 860 g também excede a massa do cone inicial de 1 749,6 g."},"takeaway":"Use semelhança para achar a altura retirada antes de calcular o volume da perfuração.","key":"matematica:M441","area":"matematica","year":2023,"number":136,"answer":"B","subject":"Geometria espacial","topic":"Volumes e capacidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A média salarial é ponderada","steps":["Calcule a folha salarial: 75 × 2 000 + 25 × 7 000 = 325 000 reais.","Divida pelos 100 funcionários, não pelo número de setores.","A média é R$ 3 250,00, C."],"alternatives":{"A":"R$ 2 000 é o salário mais frequente, não a média dos cem funcionários.","B":"R$ 2 500 não corresponde à folha total dividida pelos cem trabalhadores.","C":"R$ 325 000 divididos por cem resultam na média de R$ 3 250.","D":"R$ 4 500 é a média simples dos dois salários, ignorando os tamanhos dos setores.","E":"R$ 9 000 soma os dois valores e não é uma média salarial."},"takeaway":"Cada salário deve aparecer tantas vezes quanto o número de funcionários que o recebe.","key":"matematica:M643","area":"matematica","year":2023,"number":137,"answer":"C","subject":"Estatística","topic":"Média, mediana e moda","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Pare no mês seguinte à ultrapassagem","steps":["As vendas de I aumentam dez por mês e as de II caem vinte.","Em julho são 110 e 130; em agosto são 120 e 110, quando I supera II.","A produção de II cessa no mês seguinte, setembro: D."],"alternatives":{"A":"Em junho I ainda vende 100 contra 150 de II.","B":"Em julho I ainda fica abaixo, com 110 contra 130.","C":"Agosto é o mês da primeira ultrapassagem, não o da interrupção.","D":"Setembro é o mês seguinte a agosto, quando I passa a vender mais.","E":"Outubro posterga a decisão por um mês além do enunciado."},"takeaway":"Leia separadamente o momento em que uma condição ocorre e o momento da ação decorrente.","key":"matematica:M263","area":"matematica","year":2023,"number":139,"answer":"D","subject":"Álgebra e Funções","topic":"Função afim e modelos lineares","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[17],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Use frequências, não apenas os valores distintos","steps":["As frequências para 1 a 7 viagens são 10, 10, 55, 25, 0, 50 e 10.","A moda é 3; as posições 80 e 81 estão no grupo de 4 viagens, logo mediana 4.","A média é 665/160 = 4,15625; portanto moda < mediana < média, E."],"alternatives":{"A":"A mediana 4 difere da média 4,15625 e ambas são maiores que a moda 3.","B":"Mediana 4 e moda 3 não são iguais, embora ambas fiquem abaixo da média.","C":"A moda é o menor dos três valores, não o maior.","D":"A média 4,15625 é maior, não menor que a mediana 4.","E":"A ordenação é 3 < 4 < 4,15625, correspondente à alternativa E."},"takeaway":"Num gráfico de frequências, o eixo das quantidades informa quantas vezes cada observação entra na conta.","key":"matematica:M644","area":"matematica","year":2023,"number":140,"answer":"E","subject":"Estatística","topic":"Média, mediana e moda","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[17],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Sorteiam-se cartões, não pessoas equiprováveis","steps":["Há 200 cartões do primeiro ano, 2 × 150 = 300 do segundo e 3 × 100 = 300 do terceiro.","O total é 800 cartões e os favoráveis são os 300 do terceiro ano.","A probabilidade é 300/800 = 3/8, E."],"alternatives":{"A":"Metade exigiria 400 cartões favoráveis, mas há trezentos.","B":"Um terço não considera corretamente os 800 cartões totais.","C":"Um oitavo contaria só cem nomes, sem os três cartões por aluno.","D":"2/9 usa a proporção de pessoas do terceiro ano entre inscritos, não a de cartões.","E":"Três cartões por cem alunos dão 300 favoráveis entre 800 igualmente sorteáveis."},"takeaway":"Identifique o objeto equiprovável do sorteio: múltiplos bilhetes mudam a chance por pessoa.","key":"matematica:M703","area":"matematica","year":2023,"number":141,"answer":"E","subject":"Probabilidade e Análise combinatória","topic":"Probabilidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Distribua o volume restante por pessoas e dias","steps":["O volume disponível é πr²h = 3 × 25 × 1,5 = 112,5 m³ = 112 500 L.","Divida por 75 moradores e dez dias: 150 L por pessoa por dia.","A economia em relação aos 200 L habituais é 50 L, A."],"alternatives":{"A":"Reduzir 200 para 150 L por pessoa por dia economiza exatamente 50 L.","B":"Economizar 60 L seria suficiente, mas não é a redução mínima.","C":"Oitenta litros de economia ultrapassam a necessidade mínima calculada.","D":"140 L confundem a economia necessária com uma redução muito maior.","E":"150 L é o consumo permitido, não a quantidade economizada."},"takeaway":"A pergunta pede economia, então subtraia o consumo permitido do consumo habitual.","key":"matematica:M442","area":"matematica","year":2023,"number":142,"answer":"A","subject":"Geometria espacial","topic":"Volumes e capacidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Amplie a capacidade pela redução da fila","steps":["A lista deste ano é 400 × 1,10 = 440 nomes.","Reduzir essa espera em 25% requer mais 110 vagas, pois 0,25 × 440 = 110.","Cada nova sala oferece dez vagas: 110/10 = 11 salas, B."],"alternatives":{"A":"Dez salas abrem cem vagas, menos que as 110 necessárias.","B":"Onze salas acrescentam exatamente 110 vagas e reduzem a lista a 330.","C":"Treze salas excedem a ampliação mínima e não atendem ao pedido de mínimo.","D":"Trinta salas representam trezentas vagas, muito acima da redução necessária.","E":"Trinta e três confunde o tamanho final da lista em dezenas com novas salas."},"takeaway":"O percentual se aplica à fila de espera atual, não às vagas antigas nem ao total de inscritos.","key":"matematica:M206","area":"matematica","year":2023,"number":143,"answer":"B","subject":"Aritmética e Matemática básica","topic":"Raciocínio lógico e otimização aritmética","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Vazão é área da base vezes subida por hora","steps":["Entre 6 h e 8 h, o nível sobe 1,1 − 0,5 = 0,6 m em duas horas.","A subida é 0,3 m/h, confirmada pelos outros intervalos.","Multiplique pela base de 3 m²: vazão 0,9 m³/h, C."],"alternatives":{"A":"0,3 m/h é a taxa de aumento da altura, não a vazão volumétrica.","B":"0,5 m é a altura inicial e não uma taxa de volume por hora.","C":"3 m² × 0,3 m/h = 0,9 m³/h é a vazão constante.","D":"1,8 m³ é o volume que entrou em duas horas, não em uma.","E":"2,7 m é a variação total de nível entre 6 h e 15 h, não a vazão."},"takeaway":"Altura por tempo vira volume por tempo quando multiplicada pela área constante da base.","key":"matematica:M008","area":"matematica","year":2023,"number":144,"answer":"C","subject":"Aritmética e Matemática básica","topic":"Razão, proporção e regra de três","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O mesmo arco define o mesmo ângulo inscrito","steps":["A e B fixam uma corda e Q₁ define uma circunferência passando por esses pontos.","Vértices no mesmo arco capaz de AB enxergam a corda com o mesmo ângulo.","No desenho, Q₃ está nessa posição, logo recebe a bola: B."],"alternatives":{"A":"Q₂ não está no mesmo arco capaz definido por A, B e Q₁.","B":"Q₃ pertence ao arco correspondente e mantém o ângulo sob o qual se vê AB.","C":"Q₄ não ocupa o arco capaz do ângulo indicado.","D":"Q₅ pertence a outra posição geométrica e não conserva o ângulo de Q₁.","E":"Q₆ não está na circunferência correspondente ao mesmo ângulo inscrito."},"takeaway":"Igualdade de distância à trave não basta: o critério é o ângulo que subtende o segmento AB.","key":"matematica:M417","area":"matematica","year":2023,"number":145,"answer":"B","subject":"Geometria plana","topic":"Ângulos, circunferências e polígonos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Some os lados contando vértices duas vezes","steps":["Os vértices em PA de razão 2 só podem ser 1, 3, 5 ou 2, 4, 6.","A soma dos números é 21; somar os três lados conta os vértices duas vezes: 3S = 21 + 9 ou 21 + 12.","Logo S é 10 ou 11. São realizáveis com meios 6, 2, 4 para pares 1–3, 3–5, 5–1, e 5, 1, 3 para 2–4, 4–6, 6–2: E."],"alternatives":{"A":"Sete ignora a contagem duplicada dos vértices na soma dos lados.","B":"Nove não é nenhum dos dois valores obtidos com as PAs possíveis.","C":"Nem sete nem nove satisfazem 3S = 21 mais a soma dos vértices.","D":"Nove e doze são somas dos vértices, não as somas de cada lado.","E":"As duas escolhas de vértices produzem e permitem construir lados de soma dez ou onze."},"takeaway":"Em figuras mágicas, some por dois caminhos e verifique quantas vezes cada posição foi contada.","key":"matematica:M325","area":"matematica","year":2023,"number":146,"answer":"E","subject":"Álgebra e Funções","topic":"Sequências, PA e PG","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O pacote precisa atender duas pessoas","steps":["Pela regra do exercício, cada pessoa precisa de 30 g por dia; o casal, 60 g.","Em trinta dias são 1 800 g; cada pacote oferece 18 × 15 = 270 g de carboidratos.","1 800/270 ≈ 6,67, exigindo sete pacotes, D. Trata-se da hipótese matemática, não de orientação nutricional individual."],"alternatives":{"A":"Um pacote oferece 270 g, insuficientes para os 1 800 g necessários no modelo.","B":"Quatro pacotes poderiam vir de esquecer uma das duas pessoas.","C":"Seis pacotes fornecem 1 620 g, abaixo dos 1 800 g.","D":"Sete é o menor inteiro que cobre o consumo total calculado.","E":"Oito pacotes atenderiam, mas não constituem a compra mínima."},"takeaway":"Calcule pessoas × dias × consumo e arredonde para cima apenas no número de pacotes.","key":"matematica:M009","area":"matematica","year":2023,"number":147,"answer":"D","subject":"Aritmética e Matemática básica","topic":"Razão, proporção e regra de três","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[20],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O cabo é a hipotenusa","steps":["Como sen α = h/L, o comprimento é L = h/sen α.","As opções dão 22 m, 12√2 m e 12√3 m, respectivamente.","O menor é 12√2 ≈ 16,97 m, opção II e alternativa C."],"alternatives":{"A":"22√3/3 não é nenhum dos comprimentos calculados para as três instalações.","B":"11√2 combina a altura de uma opção com o ângulo de outra.","C":"A opção II dá 12/sen 45° = 12√2 e é a menor.","D":"12√3 corresponde à opção III e é maior que 12√2.","E":"22 corresponde à opção I e supera o comprimento da opção II."},"takeaway":"Ângulo com o chão: a altura é cateto oposto e o cabo é hipotenusa.","key":"matematica:M781","area":"matematica","year":2023,"number":148,"answer":"C","subject":"Trigonometria","topic":"Razões trigonométricas e aplicações geométricas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[20],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Coloque desenho e realidade na mesma unidade","steps":["A altitude máxima desenhada é um quadradinho, de 1 cm.","A altitude real correspondente é 5 km = 500 000 cm.","A escala é 1 cm : 500 000 cm, ou 1 : 500 000, E."],"alternatives":{"A":"1 : 5 mistura o centímetro desenhado com quilômetros reais.","B":"Onze não é a razão de medidas correspondentes na mesma unidade.","C":"Cinquenta e cinco não decorre da altura de um quadradinho indicada na tela.","D":"5 000 é a distância em metros, ainda incompatível com o centímetro do desenho.","E":"Converter cinco quilômetros para centímetros produz o denominador 500 000."},"takeaway":"Escala é uma razão adimensional: converta as duas medidas para a mesma unidade.","key":"matematica:M121","area":"matematica","year":2023,"number":149,"answer":"E","subject":"Aritmética e Matemática básica","topic":"Escalas e conversões de unidades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[20],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Noventa por cento vira fator decimal","steps":["O modelo afirma que C corresponde a 90% de q após a primeira hora.","90/100 = 0,9, portanto C = 0,9q.","A é a tradução algébrica; o modelo não autoriza decidir quando dirigir com segurança."],"alternatives":{"A":"Multiplicar q por 0,9 representa exatamente noventa por cento de q.","B":"0,1q representa dez por cento, não a fração remanescente indicada.","C":"Subtrair de um não representa a proporcionalidade descrita.","D":"1 − 0,9q também introduz um termo constante sem base no enunciado.","E":"Subtrair dez unidades não equivale a diminuir dez por cento de uma quantidade variável."},"takeaway":"Percentual de uma quantidade é multiplicação por uma fração, não subtração de um número fixo.","key":"matematica:M264","area":"matematica","year":2023,"number":150,"answer":"A","subject":"Álgebra e Funções","topic":"Função afim e modelos lineares","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Compare as coordenadas no mesmo instante","steps":["O eixo horizontal informa A e o vertical informa B.","A vale mais quando a coordenada horizontal do ponto supera a vertical, isto é, abaixo da reta B = A.","Isso ocorre às 9 h, 12 h, 13 h e 14 h: quatro instantes, B. Às 10 h e 11 h há igualdade."],"alternatives":{"A":"Há quatro pontos favoráveis, não apenas três.","B":"Os pontos de 9 h, 12 h, 13 h e 14 h têm A maior que B.","C":"Seis incluiria indevidamente os dois pontos de igualdade, às 10 h e 11 h.","D":"Sete inclui instantes em que B não é menor que A.","E":"O gráfico tem nove instantes, mas a condição só vale em quatro deles."},"takeaway":"Num gráfico com duas variáveis nos eixos, compare coordenadas, não a altura da curva como numa série temporal comum.","key":"matematica:M554","area":"matematica","year":2023,"number":151,"answer":"B","subject":"Estatística","topic":"Leitura de gráficos e tabelas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Use as propriedades do logaritmo","steps":["A expressão equivale a N = 10 log₁₀(I/I₀).","I/I₀ = 8 × 10⁴ e log 8 = 3 log 2 ≈ 0,9; assim N = 10 × 4,9 = 49 dB.","Como 48 < 49 < 55, aplica-se a medida II, B."],"alternatives":{"A":"A medida I vale até 48 dB; o resultado é 49 dB.","B":"Quarenta e nove decibéis pertencem ao intervalo de aplicação da medida II.","C":"A medida III começa acima de 55 dB, maior que o nível calculado.","D":"A medida IV exige nível superior a 80 dB.","E":"A medida V requer mais de 115 dB, muito acima de 49 dB."},"takeaway":"Dividir potências de dez subtrai expoentes; só depois aplique o logaritmo e o fator dez.","key":"matematica:M304","area":"matematica","year":2023,"number":152,"answer":"B","subject":"Álgebra e Funções","topic":"Funções exponenciais e logaritmos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Minimize a espera antes do seu atendimento","steps":["Multiplique o tempo médio pela quantidade de pessoas à frente.","Os tempos são 60, 54, 30, 30 e 27 minutos, para caixas I a V.","A menor espera é 27 minutos no caixa V, E; não se acrescenta seu próprio atendimento ao tempo de espera."],"alternatives":{"A":"O caixa I exige 5 × 12 = 60 minutos de espera.","B":"O caixa II exige 9 × 6 = 54 minutos de espera.","C":"O caixa III exige 6 × 5 = 30 minutos, mais que 27.","D":"O caixa IV também exige 2 × 15 = 30 minutos.","E":"O caixa V tem 3 × 9 = 27 minutos, o menor tempo antes do atendimento."},"takeaway":"Fila menor não garante espera menor: combine quantidade de pessoas e duração média do serviço.","key":"matematica:M207","area":"matematica","year":2023,"number":153,"answer":"E","subject":"Aritmética e Matemática básica","topic":"Raciocínio lógico e otimização aritmética","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Dois raios e um arco limitam a região","steps":["O centro do círculo coincide com o vértice do telhado.","Os lados que saem desse vértice recortam a lua por duas direções radiais.","A parte encoberta é um setor circular, B, não somente um arco nem um segmento limitado por corda."],"alternatives":{"A":"Cone é um sólido tridimensional; a figura pedida é uma região plana.","B":"Dois raios e o arco correspondente delimitam um setor circular.","C":"Segmento circular é limitado por uma corda e um arco, não por dois raios.","D":"A borda circular impede que a região seja apenas um triângulo.","E":"O arco é só uma linha da borda e não toda a região encoberta."},"takeaway":"Diferencie setor circular, segmento circular, arco e círculo pelo tipo de fronteira.","key":"matematica:M418","area":"matematica","year":2023,"number":154,"answer":"B","subject":"Geometria plana","topic":"Ângulos, circunferências e polígonos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A faixa ocupa a diferença de dois quadrados","steps":["A piscina tem lado √400 = 20 m.","A calçada acrescenta cinco metros de cada lado, formando um quadrado externo de lado 30 m.","Sua área é 30² − 20² = 900 − 400 = 500 m², D."],"alternatives":{"A":"Mil metros quadrados não resultam da diferença entre as áreas externa e interna.","B":"900 m² é a área total de piscina mais calçada.","C":"600 m² não corresponde à faixa de largura cinco em todo o contorno.","D":"A área da calçada é a área externa de 900 menos a piscina de 400.","E":"400 m² é a área da piscina, que não será contada como calçada."},"takeaway":"Largura ao redor aumenta cada dimensão duas vezes; inclua também os quatro cantos da faixa.","key":"matematica:M370","area":"matematica","year":2023,"number":155,"answer":"D","subject":"Geometria plana","topic":"Áreas e perímetros","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Sem sinal significa gráfico sobre o eixo do tempo","steps":["O sinal é nulo de 10 a 12 minutos e de 16 a 20 minutos.","As durações são 2 e 4 minutos, não os valores das extremidades.","O total é 6 minutos, A; os trechos de sinal fraco não entram nessa soma."],"alternatives":{"A":"Dois minutos no primeiro intervalo mais quatro no segundo totalizam seis.","B":"Oito inclui tempo que não permanece em intensidade zero.","C":"Dez não corresponde à soma dos dois segmentos sobre o eixo.","D":"Quatorze pode confundir instantes do gráfico com duração sem sinal.","E":"Vinte e quatro minutos são o complemento: tempo com algum sinal."},"takeaway":"Para duração em um intervalo, subtraia o início do fim e some apenas os intervalos pertinentes.","key":"matematica:M555","area":"matematica","year":2023,"number":156,"answer":"A","subject":"Estatística","topic":"Leitura de gráficos e tabelas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A condição exige duas desigualdades simultâneas","steps":["Trace mentalmente as linhas massa = 80 kg e altura = 1,65 m.","Procure pontos à esquerda da primeira e acima da segunda, sem incluir a igualdade.","São dois entre dez estudantes: 2/10 × 100 = 20%, B."],"alternatives":{"A":"Dez por cento contaria apenas um dos dois estudantes que satisfazem ambas as condições.","B":"Dois pontos entre dez observações correspondem a vinte por cento.","C":"Trinta por cento incluiria um ponto que não satisfaz as duas desigualdades.","D":"Metade da amostra não está simultaneamente abaixo de 80 kg e acima de 1,65 m.","E":"Setenta por cento não corresponde ao quadrante solicitado no gráfico."},"takeaway":"Abaixo e acima são condições estritas: pontos sobre a linha da média não entram.","key":"matematica:M645","area":"matematica","year":2023,"number":157,"answer":"B","subject":"Estatística","topic":"Média, mediana e moda","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Escreva o lucro após todos os pagamentos","steps":["Com a ajudantes, a pesca é 200 + 100a kg para a ≥ 1; a receita é 1 000 + 500a reais.","Desconte 4% da receita, R$ 900 fixos e R$ 250 por ajudante: L = 0,96(1 000 + 500a) − 900 − 250a = 60 + 230a.","L ≥ 800 exige a ≥ 740/230 ≈ 3,22. O menor inteiro permitido é quatro, D."],"alternatives":{"A":"Um ajudante dá lucro de R$ 290, inferior à meta de oitocentos.","B":"Dois ajudantes dão lucro de R$ 520, ainda insuficiente.","C":"Três ajudantes dão lucro de R$ 750 e ainda não alcançam a meta.","D":"Quatro ajudantes dão lucro de R$ 980 e são o mínimo necessário.","E":"Cinco ajudantes atingem a meta, mas não são a contratação mínima."},"takeaway":"Os quatro por cento são repartidos entre os ajudantes: não multiplique esse percentual pelo número deles.","key":"matematica:M231","area":"matematica","year":2023,"number":158,"answer":"D","subject":"Álgebra e Funções","topic":"Equações, sistemas e inequações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Resolva a potência pelo número de ciclos","steps":["Cinco litros atendem a 5 × 200 000 = 1 000 000 larvas.","Partindo de cem, é preciso multiplicar a população por 10 000 = 10⁴.","São quatro ciclos de três dias: doze dias, D."],"alternatives":{"A":"Dois dias nem completam um ciclo de multiplicação por dez.","B":"Quatro é o número de ciclos, não o total de dias.","C":"Em seis dias ocorrem dois ciclos, resultando em dez mil larvas.","D":"Em doze dias, cem vezes dez elevado a quatro alcança um milhão.","E":"Em dezoito dias são seis ciclos, ultrapassando a população atendida pelo produto."},"takeaway":"Separe tempo por ciclo, quantidade de ciclos e fator de crescimento em cada ciclo.","key":"matematica:M797","area":"matematica","year":2023,"number":159,"answer":"D","subject":"Matemática financeira","topic":"Juros e crescimento financeiro","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Conte as senhas antes de comparar chances","steps":["No tipo I há 68 × 67 × 66 × 65 possibilidades, pois todos os caracteres são distintos.","No tipo II há 52 × 51 × 50 × 10 × 6; no III, 52 × 51 × 10 × 9 × 6 × 5.","O primeiro produto é maior que o segundo, que supera o terceiro. Chances inversas dão p₁ < p₂ < p₃: A, supondo senhas equiprováveis em cada tipo."],"alternatives":{"A":"A maior quantidade de senhas possíveis corresponde à menor chance de adivinhação.","B":"O tipo I vence, mas não por ser mais curto: vence pelo total de possibilidades.","C":"Ter mais letras em posições fixadas não produz mais possibilidades que o tipo I.","D":"A contagem mostra a ordem inversa à afirmada na alternativa.","E":"Mais caracteres não garante mais senhas quando suas categorias e posições são restritas."},"takeaway":"Comprimento sozinho não mede segurança num modelo combinatório; conte também as restrições de cada posição.","key":"matematica:M704","area":"matematica","year":2023,"number":160,"answer":"A","subject":"Probabilidade e Análise combinatória","topic":"Probabilidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A entrada reduz o valor efetivamente financiado","steps":["As parcelas valem 1 500 × 1,20/3 = 600 reais; após a entrada, ficam financiados 900 reais.","Com x = 1 + i, a equivalência é 900 = 600/x + 600/x², ou 3x² − 2x − 2 = 0.","A raiz positiva é x = (2 + √28)/6 ≈ 7,29/6 = 1,215; portanto i = 21,5% ao mês, D."],"alternatives":{"A":"6,7% divide o acréscimo total por três, sem considerar entrada e datas.","B":"Dez por cento não satisfaz a equivalência financeira das duas parcelas futuras.","C":"Vinte por cento é o acréscimo sobre o preço à vista, não a taxa mensal efetiva.","D":"A raiz positiva da equação financeira fornece fator 1,215 e taxa de 21,5%.","E":"23,3% não resulta da equivalência com entrada de seiscentos e duas prestações futuras."},"takeaway":"Em prestações com entrada, compare valores numa mesma data; acréscimo total não é taxa mensal.","key":"matematica:M798","area":"matematica","year":2023,"number":161,"answer":"D","subject":"Matemática financeira","topic":"Juros e crescimento financeiro","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Some taxa fixa e preço por volume","steps":["A taxa de bombeamento é de R$ 500 independentemente do volume.","Cada metro cúbico acrescenta R$ 250, isto é, a parcela variável é 250x.","O preço total é y = 250x + 500, alternativa D."],"alternatives":{"A":"250x representa apenas o concreto e ignora a taxa de bombeamento.","B":"500x transforma a taxa fixa em custo por metro cúbico.","C":"750x também faz a taxa fixa variar com o volume contratado.","D":"A expressão soma os quinhentos fixos aos duzentos e cinquenta por metro cúbico.","E":"A alternativa troca o custo fixo de quinhentos pelo unitário de duzentos e cinquenta."},"takeaway":"Na função afim, o termo independente é o custo fixo e o coeficiente de x é o custo unitário.","key":"matematica:M265","area":"matematica","year":2023,"number":162,"answer":"D","subject":"Álgebra e Funções","topic":"Função afim e modelos lineares","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Distância constante não significa ficar parado","steps":["Nos primeiros dez minutos a distância à base cresce linearmente de zero a três quilômetros.","Entre 10 e 20 minutos, mover-se com distância constante exige um arco de circunferência centrado na base.","Depois há retorno radial até a base. O percurso raio–arco–raio corresponde a A."],"alternatives":{"A":"Dois segmentos radiais ligados por arco centrado na base reproduzem os três trechos.","B":"Um segmento reto entre os extremos não mantém a distância à base durante o trecho central.","C":"O percurso aberto não inclui o arco de distância constante e o retorno completo.","D":"O trecho superior reto também varia a distância à base, contrariando o patamar.","E":"O conjunto arco e diâmetro não apresenta a sequência radial, circular e radial indicada a partir da base."},"takeaway":"Não desenhe o gráfico como se fosse o mapa: distância à base é uma grandeza escalar ao longo da trajetória.","key":"matematica:M430","area":"matematica","year":2023,"number":163,"answer":"A","subject":"Geometria plana","topic":"Simetria e transformações geométricas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Item oficialmente anulado: não atribua letra","steps":["O gabarito oficial registra anulação, portanto não existe alternativa oficial a marcar como correta.","O gráfico apresenta coberturas vacinais; adultos de 20 a 29 anos têm a menor barra entre os grupos.","Cobertura vacinal e risco de exposição são conceitos diferentes. Esta observação didática não é apresentada como justificativa oficial da anulação, que o gabarito não informa."],"alternatives":{"A":"Indígenas aparecem com cobertura maior que adultos jovens; não há letra oficial válida neste item anulado.","B":"Gestantes não têm a menor barra; isso não autoriza atribuir uma resposta oficial a um item anulado.","C":"Doentes crônicos apresentam cobertura intermediária, sem que ela determine sozinha o risco de exposição.","D":"Adultos jovens têm a menor cobertura mostrada, mas o registro oficial é Anulada, não a letra D.","E":"Crianças têm alta cobertura relativa; o gabarito anulado não valida nenhuma das opções."},"takeaway":"Respeite a anulação e não transforme uma interpretação de gráfico numa resposta oficial inexistente.","key":"matematica:M556","area":"matematica","year":2023,"number":164,"answer":"Anulada","subject":"Estatística","topic":"Leitura de gráficos e tabelas","status":"verified","annulled":true,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Some pisos, espelhos e duas laterais","steps":["Os três pisos têm área total 3 × 1 × 0,25 = 0,75 m²; os três espelhos, 3 × 1 × 0,20 = 0,60 m².","Cada lateral em degraus tem área 0,25 × (0,20 + 0,40 + 0,60) = 0,30 m².","As duas laterais somam 0,60 m²: total 0,75 + 0,60 + 0,60 = 1,95 m², E. Não se revestem base e fundo encostado na parede."],"alternatives":{"A":"1,20 m² não inclui corretamente as superfícies horizontais, verticais e duas laterais.","B":"1,35 m² é só a soma de pisos e espelhos, sem as laterais.","C":"1,65 m² inclui apenas uma das duas laterais além dos pisos e espelhos.","D":"1,80 m² não corresponde à soma das três categorias de faces solicitadas.","E":"As áreas de pisos, espelhos e laterais totalizam 1,95 m²."},"takeaway":"Conte apenas as superfícies pedidas e decomponha cada lateral em retângulos de alturas sucessivas.","key":"matematica:M482","area":"matematica","year":2023,"number":165,"answer":"E","subject":"Geometria espacial","topic":"Áreas de superfícies e planificações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Pondere as horas pelo gasto de cada atividade","steps":["Multiplique as horas de cada coluna pelo gasto horário correspondente e some em cada dia.","Os totais do quadro são 1 614, 1 558, 1 748, 1 528 e 1 612, de segunda a sexta, nas unidades fornecidas.","O maior é 1 748, na quarta-feira: C. Somar só as horas ignoraria intensidades diferentes."],"alternatives":{"A":"Segunda soma 248 + 382 + 984 = 1 614, abaixo de quarta.","B":"Terça soma 124 + 764 + 178 + 492 = 1 558.","C":"Quarta soma 1 146 + 356 + 246 = 1 748, o maior total.","D":"Quinta tem duas horas de corrida, totalizando 1 528.","E":"Sexta soma 382 + 1 230 = 1 612, também abaixo de quarta."},"takeaway":"Uma tabela de tempos precisa ser ponderada pela taxa de gasto, não ordenada pela duração total.","key":"matematica:M557","area":"matematica","year":2023,"number":166,"answer":"C","subject":"Estatística","topic":"Leitura de gráficos e tabelas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Arredonde os pacotes antes de calcular o desconto","steps":["A proporção é 6 000/1 200 = cinco folhas por aluno: 1 150 alunos precisam de 5 750 folhas.","Como só se compram embalagens de cem, são necessárias 58, a custo de R$ 232.","A redução mínima é 12/232 × 100 ≈ 5,17%, pertencente a (5,0; 5,5), A."],"alternatives":{"A":"O desconto mínimo de aproximadamente 5,17% está no intervalo indicado.","B":"Oito por cento daria redução maior que a necessária, não a mínima calculada.","C":"Cerca de doze por cento excede o desconto necessário para chegar a R$ 220.","D":"Vinte por cento também supera amplamente a redução mínima.","E":"Um desconto entre 3,5% e 4% não reduz R$ 232 a R$ 220."},"takeaway":"Em compras por embalagens, arredonde a quantidade para cima antes de calcular preço e desconto.","key":"matematica:M813","area":"matematica","year":2023,"number":167,"answer":"A","subject":"Matemática financeira","topic":"Descontos, preços e comparação de propostas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A segunda urna depende do primeiro algarismo","steps":["Para 50, a unidade zero sai com chance 1/10; as dezenas permitidas são 1 a 5, dando 1/5.","Para 02, a unidade dois também tem chance 1/10, mas as dezenas podem ser 0 a 5, dando 1/6.","As probabilidades são 1/50 e 1/60, respectivamente: A."],"alternatives":{"A":"O produto das probabilidades condicionadas dá 1/50 para 50 e 1/60 para 02.","B":"Para unidade dois existem seis dezenas possíveis, não cinco.","C":"A chance da dezena zero após unidade dois não é um, mas um sexto.","D":"As inscrições não ficam equiprováveis nesse procedimento por etapas.","E":"As segundas urnas não têm dez bolas em ambos os casos, então não se obtém 1/100."},"takeaway":"Quando a composição da segunda urna muda, use probabilidade condicional em vez de dividir pelo total de inscritos.","key":"matematica:M705","area":"matematica","year":2023,"number":168,"answer":"A","subject":"Probabilidade e Análise combinatória","topic":"Probabilidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A profundidade é o expoente da progressão","steps":["A cada metro, a intensidade anterior é multiplicada por 2/3.","Na profundidade h, L = L₀(2/3)ʰ.","Para seis metros, L = 64L₀/729, D; a superfície corresponde ao expoente zero."],"alternatives":{"A":"L₀/9 não corresponde à sexta potência da razão 2/3.","B":"16L₀/27 não mantém o mesmo expoente no numerador e no denominador.","C":"32L₀/243 corresponde à quinta potência e à profundidade de cinco metros.","D":"A sexta potência de 2/3 é 64/729, conforme o padrão.","E":"128L₀/2 187 corresponde à sétima potência, um metro além do pedido."},"takeaway":"O índice da profundidade começa em zero na superfície: evite deslocar o expoente em uma unidade.","key":"matematica:M326","area":"matematica","year":2023,"number":169,"answer":"D","subject":"Álgebra e Funções","topic":"Sequências, PA e PG","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O menor valor ocorre no vértice","steps":["A fórmula oficial é V(x) = x²/4 − 10x + 105, em milhares de reais.","A parábola é voltada para cima; o vértice está em x = 10/(2 × 1/4) = 20, dentro do mês.","V(20) = 100 − 200 + 105 = 5. Como 4 ≤ 5 < 10, o desempenho é ruim, D."],"alternatives":{"A":"Ótimo exige mínimo de pelo menos 24 mil reais, não cinco.","B":"Bom exige mínimo entre vinte e vinte e quatro mil.","C":"Normal exige mínimo de dez mil, superior ao calculado.","D":"Cinco mil pertence ao intervalo de quatro a menos de dez mil.","E":"Péssimo exige mínimo inferior a quatro mil, mas o resultado é cinco."},"takeaway":"Para classificar pelo pior dia, minimize a função; não use seu valor inicial, final ou máximo.","key":"matematica:M287","area":"matematica","year":2023,"number":170,"answer":"D","subject":"Álgebra e Funções","topic":"Função quadrática","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Converta o período primeiro para dias","steps":["São 20 × 52 = 1 040 anos Haab.","Isso equivale a 1 040 × 365 = 379 600 dias.","Dividindo por 260 dias por Tzolkim, obtêm-se 1 460 anos Tzolkim, C."],"alternatives":{"A":"741 aproxima a conversão invertida, usando 260/365.","B":"1 040 é o número de anos Haab, antes da conversão.","C":"379 600 dias divididos por 260 fornecem 1 460 anos Tzolkim.","D":"2 100 não resulta da conversão das durações dadas.","E":"5 200 multiplica por 260 sem levar corretamente em conta 52 e 365."},"takeaway":"Nomes de unidades diferentes exigem conversão pela duração, mesmo que ambas sejam chamadas anos.","key":"matematica:M122","area":"matematica","year":2023,"number":171,"answer":"C","subject":"Aritmética e Matemática básica","topic":"Escalas e conversões de unidades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma pizza maior corresponde a um ângulo obtuso","steps":["A área de um círculo de diâmetro d é πd²/4.","Se a pizza do professor é oposta a α, a lei dos cossenos dá a² = b² + c² − 2bc cos α.","Para a² > b² + c² é preciso cos α < 0: 90° < α < 180°, alternativa C."],"alternatives":{"A":"Um ângulo agudo dá cosseno positivo e área menor, não maior.","B":"Ângulo reto produz igualdade entre as áreas, não superioridade.","C":"O ângulo obtuso torna o termo subtraído negativo e faz a² superar b² + c².","D":"Ângulo de 180° torna a figura degenerada, sem triângulo.","E":"Ângulo interno de um triângulo não pode ser maior que 180°."},"takeaway":"Quando áreas são proporcionais aos quadrados dos lados, compare-as pela lei dos cossenos.","key":"matematica:M399","area":"matematica","year":2023,"number":172,"answer":"C","subject":"Geometria plana","topic":"Semelhança, triângulos e teorema de Pitágoras","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Dividir por massa acrescenta kg ao denominador","steps":["O consumo de oxigênio é medido em mL/min.","A economia de corrida divide esse consumo pela massa em kg.","A unidade é (mL/min)/kg = mL/(min · kg), B."],"alternatives":{"A":"Minuto no numerador inverte a posição da taxa de consumo.","B":"Mililitros divididos por minuto e quilograma correspondem à definição.","C":"Multiplicar por minuto desfaz a taxa temporal que deveria permanecer no denominador.","D":"Essa alternativa inverte também a posição de mililitros e quilogramas.","E":"Quilograma no numerador multiplicaria pela massa em vez de dividir por ela."},"takeaway":"Trate unidades como fatores algébricos: dividir por uma grandeza coloca sua unidade no denominador.","key":"matematica:M123","area":"matematica","year":2023,"number":173,"answer":"B","subject":"Aritmética e Matemática básica","topic":"Escalas e conversões de unidades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Suba quatro fileiras antes de olhar à direita","steps":["A estrela está na altura da fileira E, na escada entre posições 3 e 4.","Quatro fileiras ao norte levam a F, G, H e I.","À direita ficam as posições 4, 5 e 6; a terceira é I6, alternativa E."],"alternatives":{"A":"A6 desloca para a extremidade inferior em vez de subir ao norte.","B":"H1 combina a fileira errada com o lado esquerdo da escada.","C":"H6 conta só três fileiras acima da E.","D":"I1 acerta a fileira, mas escolhe o lado esquerdo e a posição errada.","E":"I6 resulta de subir quatro fileiras e contar a terceira poltrona à direita."},"takeaway":"Use a orientação de quem está no mapa e conte deslocamentos, sem incluir a posição inicial.","key":"matematica:M536","area":"matematica","year":2023,"number":174,"answer":"E","subject":"Geometria analítica","topic":"Plano cartesiano, distâncias e retas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Separe preço unitário e preço da cartela","steps":["Se r e b são preços unitários, 18b + 9r = 32,40, ou 2b + r = 3,60.","A segunda informação dá b − r = r + 0,05, portanto b = 2r + 0,05.","Substituindo, 5r + 0,10 = 3,60: r = 0,70 e a cartela vermelha custa 9 × 0,70 = R$ 6,30, B."],"alternatives":{"A":"R$ 4,68 não satisfaz simultaneamente o total e a diferença entre preços unitários.","B":"Nove tíquetes a setenta centavos somam exatamente R$ 6,30.","C":"R$ 9,30 não é o preço obtido para os nove tíquetes vermelhos.","D":"R$ 10,50 não atende ao sistema de preços do enunciado.","E":"R$ 10,65 também é incompatível com as duas equações dadas."},"takeaway":"Os cinco centavos se referem a um tíquete, não ao preço de uma cartela inteira.","key":"matematica:M232","area":"matematica","year":2023,"number":175,"answer":"B","subject":"Álgebra e Funções","topic":"Equações, sistemas e inequações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"As diferenças formam uma progressão aritmética","steps":["Entre os números 1, 5, 12, 22, 35 e 51, os aumentos são 4, 7, 10, 13 e 16.","Os próximos aumentos são 19 e 22, mantendo razão três entre as diferenças.","Assim o sétimo é 70 e o oitavo é 92, E."],"alternatives":{"A":"59 não é o oitavo termo e não segue os aumentos de razão três.","B":"83 não resulta de acrescentar dezenove e vinte e dois a cinquenta e um.","C":"86 usa um aumento total incorreto para as duas novas camadas.","D":"89 fica três abaixo de 92, quebrando o crescimento das diferenças.","E":"51 + 19 + 22 = 92 é o oitavo número pentagonal."},"takeaway":"Quando os termos não são uma PA, as diferenças entre eles ainda podem revelar um padrão simples.","key":"matematica:M327","area":"matematica","year":2023,"number":176,"answer":"E","subject":"Álgebra e Funções","topic":"Sequências, PA e PG","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Altura periódica e suave começa no máximo","steps":["No movimento circular uniforme, a altura pode ser escrita h(t) = h_c + R cos(ωt), tomando t = 0 no topo.","A curva começa no máximo, desce suavemente até um mínimo e repete o ciclo.","O esboço A apresenta esse comportamento senoidal, sem quinas ou pausas artificiais."],"alternatives":{"A":"A curva suave inicia num máximo e oscila periodicamente, como uma função cosseno deslocada.","B":"Segmentos retos implicariam taxa vertical constante em trechos e quinas nos extremos.","C":"Patamares fariam a altura permanecer fixa durante intervalos, o que não ocorre no giro uniforme.","D":"Mínimos pontudos não representam a variação suave da altura na circunferência.","E":"Máximos pontudos também contradizem a suavidade da função de altura."},"takeaway":"Velocidade angular constante não torna constante a velocidade vertical da cadeira.","key":"matematica:M791","area":"matematica","year":2023,"number":177,"answer":"A","subject":"Trigonometria","topic":"Funções trigonométricas e fenômenos periódicos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Volume acumulado não desaparece quando a torneira fecha","steps":["De 0 a 3 s, o volume cresce linearmente com a vazão constante.","De 3 a 8 s, permanece no valor já liberado; de 8 a 11 s, volta a crescer com a mesma inclinação.","O gráfico contínuo com subida, patamar e subida é B."],"alternatives":{"A":"O gráfico omite o volume durante a pausa em vez de manter o valor acumulado.","B":"O patamar preserva a água já liberada e as duas rampas têm a mesma inclinação.","C":"Esse esboço se aproxima de ligar e desligar a vazão, não acumular volume.","D":"A reta sempre crescente faria sair água também nos cinco segundos de interrupção.","E":"O acumulado não pode voltar a zero durante a pausa como o desenho indica."},"takeaway":"O gráfico de vazão mostra liga/desliga; o de volume acumulado cresce ou fica constante, sem apagar o passado.","key":"matematica:M341","area":"matematica","year":2023,"number":178,"answer":"B","subject":"Álgebra e Funções","topic":"Leitura e transformação de gráficos de funções","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O sistema soma grupos de dois e uma unidade","steps":["Na convenção da figura, urapum representa um e okosa representa dois.","Cinco é 2 + 2 + 1; sete é 2 + 2 + 2 + 1.","As expressões correspondentes são okosa okosa urapum e okosa okosa okosa urapum, C."],"alternatives":{"A":"A opção soma cinco e sete, mas não segue a forma padrão de agrupar em pares mostrada na figura.","B":"A primeira expressão representa cinco, mas a segunda soma nove.","C":"A composição usa dois pares e uma unidade para cinco, e três pares e uma unidade para sete.","D":"A primeira expressão soma quatro, não cinco, e não segue o agrupamento do padrão.","E":"A segunda expressão soma oito, não sete, por trazer quatro pares."},"takeaway":"Não basta somar o valor certo: respeite também a regra de representação mostrada pelo sistema.","key":"matematica:M172","area":"matematica","year":2023,"number":179,"answer":"C","subject":"Aritmética e Matemática básica","topic":"Operações, frações e sistemas de numeração","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Compare as cinco médias de meses consecutivos","steps":["As médias são (250 + 150)/2 = 200 e (150 + 200)/2 = 175 mm nas duas primeiras janelas.","Dezembro–janeiro dá 325 mm; janeiro–fevereiro dá 275 e fevereiro–março dá 150.","A maior média é 325 mm, então o plantio começa em dezembro, alternativa C."],"alternatives":{"A":"Outubro e novembro têm média de duzentos milímetros, abaixo da máxima.","B":"Novembro e dezembro têm média de cento e setenta e cinco milímetros.","C":"Dezembro e janeiro somam 650 mm e dão a maior média, 325 mm.","D":"Janeiro tem maior chuva isolada, mas com fevereiro sua média cai a 275 mm.","E":"Fevereiro e março têm média de cento e cinquenta milímetros."},"takeaway":"A melhor janela de dois meses não precisa começar no mês de maior chuva isolada.","key":"matematica:M646","area":"matematica","year":2023,"number":180,"answer":"C","subject":"Estatística","topic":"Média, mediana e moda","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2023/ENEM-2023-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"matematica/gab_2023.pdf","sha256":"cf40c0c8b19145440132673b11ec682ceef2e047eb1cfa1a2f19a0f908c12410","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2023.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}}];
